// ===== Tiana grande (hero): quita el fondo claro de la imagen =====
(function () {
  var b64 = "data:image/jpeg;base64,";
  var img = new Image();
  img.onload = function () {
    var canvas = document.getElementById('tianahero');
    canvas.width = img.naturalWidth;
    canvas.height = img.naturalHeight;
    var ctx = canvas.getContext('2d');
    ctx.drawImage(img, 0, 0);
    var imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    var data = imageData.data;
    // background color of card: #F7F3EC = rgb(247,243,236)
    var bgR = 247, bgG = 243, bgB = 236;
    for (var i = 0; i < data.length; i += 4) {
      var r = data[i], g = data[i + 1], b = data[i + 2];
      // brightness of pixel
      var brightness = (r + g + b) / 3;
      // if pixel is very light (near white/cream background), make transparent
      // threshold: if brightness > 200 and not strongly colored
      var maxChannel = Math.max(r, g, b);
      var minChannel = Math.min(r, g, b);
      var saturation = maxChannel > 0 ? (maxChannel - minChannel) / maxChannel : 0;
      if (brightness > 195 && saturation < 0.18) {
        // fully transparent
        data[i + 3] = 0;
      } else if (brightness > 175 && saturation < 0.12) {
        // semi transparent
        data[i + 3] = Math.max(0, Math.min(255, Math.round((1 - (brightness - 175) / 80) * 255)));
      } else if (brightness > 155 && saturation < 0.08) {
        data[i + 3] = Math.round((1 - (brightness - 155) / 40) * 255);
      }
    }
    ctx.putImageData(imageData, 0, 0);
  };
  img.src = b64;
})();

